      SUBROUTINE RDFAILC---- MARK PLACE OF FATAL INPUT ERRORC-------------------------------------------------------------------      INCLUDE 'IODATA.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RDBUFF.CIN'C-------------------------------------------------------------------      WRITE (NOUT,910) ILINE, KTEXT      WRITE (NOUT,920) IMARK, (' ', I = 1, IMARK), '?'      NFAIL = NFAIL + 1      RETURNC-------------------------------------------------------------------  910 FORMAT('0* LINE',I5,' * ',A80)  920 FORMAT(' * COLUMN',I3,' *',82A1)C-------------------------------------------------------------------      END